		'posts_per_page' => 4,
		'fields' => 'ids',
		'no_found_rows' => true,
		'meta_query' => array(
			array('key' => 'produto_destaque', 'value' => '1'),
			array('key' => '_thumbnail_id', 'compare' => 'EXISTS'),
		),
	));
	$featured_product_ids = array_map('intval', $featured_products->posts);
	$product_ids = $featured_product_ids;
	if (count($product_ids) < 4) {
		$recent_products = new WP_Query(array(
			'post_type' => 'produto',
			'post_status' => 'publish',
			'posts_per_page' => 4 - count($product_ids),
			'post__not_in' => $product_ids,
			'fields' => 'ids',
			'no_found_rows' => true,
			'meta_query' => array(array('key' => '_thumbnail_id', 'compare' => 'EXISTS')),
		));
		$product_ids = array_merge($product_ids, array_map('intval', $recent_products->posts));
	}
